+void HistoryModelTest::testUndoRemove()
+{
+    std::shared_ptr<HistoryModel> history = HistoryModel::self();
+    std::unique_ptr<QAbstractItemModelTester> modelTest(new QAbstractItemModelTester(history.get()));
+    history->setMaxSize(10);
+    QCOMPARE(history->rowCount(), 0);
+
+    const QString middleText = QStringLiteral("middle");
+    const QString middleUuid = QString::fromLatin1(QCryptographicHash::hash(middleText.toUtf8(), QCryptographicHash::Sha1).toHex());
+    QVERIFY(history->insert(QStringLiteral("oldest")));
+    QVERIFY(history->insert(middleText));
+    QVERIFY(history->insert(QStringLiteral("newest")));
+    QTRY_COMPARE(history->pendingJobs(), 0); // the data is written by a job
+
+    auto formatsOf = [&history](const QString &uuid) {
+        QSqlQuery query(history->m_db);
+        query.prepare(QStringLiteral("SELECT count(*) FROM aux WHERE uuid = ?"));
+        query.addBindValue(uuid);
+        return query.exec() && query.next() ? query.value(0).toInt() : -1;
+    };
+    const int formats = formatsOf(middleUuid);
+    QVERIFY(formats > 0);
+
+    QVERIFY(history->remove(middleUuid));
+    QCOMPARE(history->rowCount(), 2);
+    QCOMPARE(history->indexOf(middleUuid), -1);
+
+    QCOMPARE(formatsOf(middleUuid), 0);
+
+    // back where it was, with its data, and readable again
+    history->undo();
+    QCOMPARE(history->rowCount(), 3);
+    QCOMPARE(history->index(1, 0).data().toString(), middleText);
+    QCOMPARE(history->indexOf(middleUuid), 1);
+    QCOMPARE(formatsOf(middleUuid), formats);
+    QVERIFY(QDir(QStandardPaths::writableLocation(QStandardPaths::GenericDataLocation) + u"/klipper/data").exists(middleUuid));
+
+    // something copied meanwhile pushes the history down; the item still goes back where it was
+    QVERIFY(history->remove(middleUuid));
+    QVERIFY(history->insert(QStringLiteral("newer")));
+    history->undo();
+    QCOMPARE(history->rowCount(), 4);
+    QCOMPARE(history->index(2, 0).data().toString(), middleText);
+
+    // and gone for good once purged
+    QVERIFY(history->remove(middleUuid));
+    history->purgeRemoved();
+    history->undo();
+    QCOMPARE(history->rowCount(), 3);
+    QCOMPARE(history->indexOf(middleUuid), -1);
+
+    // copied and removed again while the first removal could still be undone
+    QVERIFY(history->insert(middleText));
+    QTRY_COMPARE(history->pendingJobs(), 0);
+    QVERIFY(history->remove(middleUuid));
+    QVERIFY(history->insert(middleText));
+    QTRY_COMPARE(history->pendingJobs(), 0);
+    QVERIFY(history->remove(middleUuid));
+    history->purgeRemoved();
+    QTRY_COMPARE(history->pendingJobs(), 0);
+    QVERIFY(!QDir(QStandardPaths::writableLocation(QStandardPaths::GenericDataLocation) + u"/klipper/data").exists(middleUuid));
+
+    history->setMaxSize(0);
+    QTRY_COMPARE(history->pendingJobs(), 0);
+}
